def fin(s,note):
    s['sourceNote']=note+NOTE; s['vocabulary']={}; save(s)
def win(tab,table,callouts=False,dialog=False,name='Table1'):
    b='<rect x="5" y="25" width="430" height="230" fill="#f4f7fb" stroke="#555"/><rect x="5" y="25" width="430" height="16" fill="#cfd9ea" stroke="#555"/>'+T(215,37,'Database : Database (Access 2007) — Table Tools',8,'middle',400)
    b+='<circle cx="22" cy="55" r="9" fill="#d9b04a" stroke="#555"/>'
    for k,t in enumerate(['Home','Create','External Data','Database Tools','Datasheet']): b+=T(50+k*70,62,t,8,'start',700)
    b+='<rect x="10" y="68" width="420" height="42" fill="#e8eef8" stroke="#aaa"/>'+T(15,85,'Views',8,'start',400)+T(75,85,'Fields & Columns',8,'start',400)+T(185,85,'Data Type & Formatting',8,'start',400)+T(345,85,'Relationships',8,'start',400)
    b+='<rect x="10" y="115" width="115" height="120" fill="#fff" stroke="#888"/>'+T(15,128,'All Tables',8,'start',700)+T(15,145,table,8,'start',700)+T(30,160,table+' : Table',8,'start',400)
    b+='<rect x="130" y="115" width="300" height="120" fill="#fff" stroke="#888"/>'+T(135,128,table,8,'start',700)+T(160,148,'ID',8,'start',700)+T(215,148,'Add New Field',8,'start',700)+T(160,165,'(New)',8,'start',400)
    b+=T(135,230,'Record: 1 of 1    No Filter    Search',7,'start',400)+T(12,250,'Datasheet View',7,'start',400)
    if dialog:
        b+='<rect x="130" y="140" width="190" height="60" fill="#f2e04a" stroke="#555"/>'+T(135,152,'Save As',8,'start',700)+T(140,168,'Table Name:',8,'start',400)+'<rect x="140" y="172" width="170" height="10" fill="#fff" stroke="#666"/>'+T(143,181,'Table1',7,'start',400)+'<rect x="215" y="188" width="40" height="10" fill="#eee" stroke="#555"/>'+T(235,196,'OK',7,'middle',700)+'<rect x="262" y="188" width="45" height="10" fill="#eee" stroke="#555"/>'+T(284,196,'Cancel',7,'middle',700)
    if callouts:
        b+=T(5,12,'Office Button',8,'start',700)+T(90,12,'Ribbon',8,'start',700)+T(190,12,'Tabs',8,'start',700)+T(5,272,'Navigation Pane',8,'start',700)+T(120,272,'Status bar',8,'start',700)
    return svg(445,285,'Microsoft Access 2007 window: '+tab,b)
